/bin/bash -lc "python - <<'PY'
import pandas as pd, numpy as np
fr=pd.read_csv('nnls_spot_fractions.csv', index_col=0)
pos=pd.read_csv('tissue_positions.csv').set_index('barcode').loc[fr.index]
coords=pos[['array_row','array_col']].astype(int)
labels=fr.idxmax(axis=1)
letter={'Tumor_Core':'T','Fibroblast_Stroma':'F','Macrophage':'M','B_Cell':'B','Endothelial':'E','T_Cell':'C'}
# print grid by row y and col x maybe array_row row and array_col col
print('coordinate ranges', coords['array_row'].min(), coords['array_row'].max(), coords['array_col'].min(), coords['array_col'].max())
for r in sorted(coords['array_row'].unique()):
    chars=[]
    for c in sorted(coords['array_col'].unique()):
        idx=np.where((coords['array_row']==r)&(coords['array_col']==c))[0]
        if len(idx)==0: chars.append(' ')
        else: chars.append(letter[labels.iloc[idx[0]]])
    print(''.join(chars))
print('\\nTumor fraction > .1 grid:')
for r in sorted(coords['array_row'].unique()):
    chars=[]
    for c in sorted(coords['array_col'].unique()):
        idx=np.where((coords['array_row']==r)&(coords['array_col']==c))[0]
        if len(idx)==0: chars.append(' ')
        else: chars.append('#' if fr['Tumor_Core'].iloc[idx[0]]>.1 else '.')
    print(''.join(chars))
PY"
